text:
{
  "entries": [
    {
      "system": "奇门",
      "element": "开门",
      "reading": "Cửa mở — thuận lợi khởi sự, công danh, xuất hành, cầu tài. Dùng khi hỏi việc mới, xin việc, khai trương; vượng nhất ở cung sinh vượng, tránh khi gặp Bạch Hổ/Đại Hung."
    },
    {
      "system": "奇门",
      "element": "休门",
      "reading": "Cửa nghỉ — tốt cầu an, chữa bệnh, hòa giải, nghỉ ngơi tích lũy. Dùng khi hỏi sức khỏe, hòa hợp gia đình; không dùng cho công danh gấp hay tranh chấp."
    },
    {
      "system": "奇门",
      "element": "生门",
      "reading": "Cửa sinh — cực tốt cầu tài, sản xuất, nuôi dưỡng, sinh con. Ưu tiên khi hỏi kinh doanh, đầu tư dài hạn; kết hợp Cửu Thiên/Thiên Phụ càng mạnh."
    },
    {
      "system": "奇门",
      "element": "伤门",
      "reading": "Cửa thương — hao tổn, tranh chấp, săn bắt, thi cử cạnh tranh. Có thể dùng chủ động khi cần tranh đấu/kiện tụng; tránh hỏi hôn nhân, hợp tác lâu dài."
    },
    {
      "system": "奇门",
      "element": "杜门",
      "reading": "Cửa bế — ẩn náu, bí mật, công nghệ, trốn tránh. Tốt nghiên cứu, che giấu, an ninh mạng; xấu cho quảng bá, khai trương, cầu danh công khai."
    },
    {
      "system": "奇门",
      "element": "景门",
      "reading": "Cửa cảnh — văn thư, thi cử, truyền thông, vẻ ngoài. Dùng hỏi học hành, giấy tờ, marketing; dễ hư danh nếu gặp Đằng Xà/Thiên Rui."
    },
    {
      "system": "奇门",
      "element": "死门",
      "reading": "Cửa tử — kết thúc, tang sự, tuyệt địa, bất động sản cũ. Tránh hầu hết việc mới; có thể dùng khi hỏi dứt điểm, phá hủy, hoặc địa điểm âm trầm."
    },
    {
      "system": "奇门",
      "element": "惊门",
      "reading": "Cửa kinh — lo sợ, kiện tụng, tin đồn, khẩu thiệt. Dùng khi hỏi tranh chấp pháp lý, lời nói; xấu hôn nhân/đối tác nếu chủ khách đều kinh."
    },
    {
      "system": "奇门",
      "element": "门开闭规则",
      "reading": "Cửa mở khi cung vượng/tương sinh với Nhật thời và không bị hình xung khắc; đóng khi cung tù tử, gặp Không Vong hoặc hung thần áp. Ứng dụng: chỉ hành sự qua cung cửa mở + tinh thần tốt."
    },
    {
      "system": "奇门",
      "element": "天蓬星",
      "reading": "Tham Lang — nước, trộm cắp, mưu trí, dục vọng, thủy lợi. Tốt mưu lược/ngầm; xấu chính danh, dễ dính thị phi dục vọng nếu gặp Bạch Hổ."
    },
    {
      "system": "奇门",
      "element": "天芮星",
      "reading": "Cự Môn — bệnh, thầy thuốc, kiện tụng, ám muội. Tốt hỏi bệnh/y thuật; hung cho hôn nhân, xuất hành xa nếu không có kỳ cứu."
    },
    {
      "system": "奇门",
      "element": "天冲星",
      "reading": "Lộc Tồn — xung kích, quyết đoán, quân sự, tốc độ. Tốt thi đấu, khởi binh, phá thế; xấu nhu hòa, thai sản, việc cần kiên nhẫn."
    },
    {
      "system": "奇门",
      "element": "天辅星",
      "reading": "Văn Khúc — văn hóa, giáo dục, quý nhân, trợ giúp. Cực tốt học hành, xin chỉ thị, cầu sư; gặp Cảnh Môn càng đẹp cho thi cử."
    },
    {
      "system": "奇门",
      "element": "天禽星",
      "reading": "Liêm Trinh trung — trung hòa, điều phối, trung tâm quyền lực. Ổn định cục, trung gian hòa giải; ít thiên lệch, dùng khi cần giữ thế trung lập."
    },
    {
      "system": "奇门",
      "element": "天心星",
      "reading": "Vũ Khúc y — y dược, mưu kế, tâm ý, kỹ thuật tinh. Tốt chữa bệnh, thiết kế, tư vấn; gặp Đỗ Môn hợp việc bí mật chuyên môn."
    },
    {
      "system": "奇门",
      "element": "天柱星",
      "reading": "Phá Quân — phá hủy, khẩu thiệt, đổ vỡ. Hung hôn nhân/hợp đồng; có thể dùng phá thế cũ, thanh lọc, sa thải dứt điểm."
    },
    {
      "system": "奇门",
      "element": "天任星",
      "reading": "Tả Phụ — xây dựng, trách nhiệm, đất đai, trung hậu. Tốt bất động sản, tích lũy, chức vụ ổn; chậm nhưng bền, hợp Sinh Môn."
    },
    {
      "system": "奇门",
      "element": "天英星",
      "reading": "Hữu Bật — lửa, huyết quang, danh tiếng nóng, tình cảm. Tốt quảng bá ngắn hạn; dễ nóng vội, tai nạn lửa máu nếu gặp Thương/Kinh."
    },
    {
      "system": "奇门",
      "element": "值符",
      "reading": "Trực Phù — thần chủ lệnh, quý nhân tối cao của cục. Gặp Trực Phù = có thế, được che chở; dùng hỏi quyền lực, xin việc quan, định chủ việc."
    },
    {
      "system": "奇门",
      "element": "腾蛇",
      "reading": "Đằng Xà — nghi hoặc, giả dối, kinh hãi, biến hóa. Cảnh báo lừa dối/giấy tờ ảo; tránh ký kết, kiểm tra kỹ tin tức và hợp đồng."
    },
    {
      "system": "奇门",
      "element": "太阴",
      "reading": "Thái Âm — che giấu, âm mưu, phụ nữ, tài liệu mật. Tốt việc ngầm, kế hoạch chưa công bố; xấu phơi bày công khai, dễ dính thị phi nữ giới."
    },
    {
      "system": "奇门",
      "element": "六合",
      "reading": "Lục Hợp — hòa hợp, môi giới, hôn nhân, giao dịch. Ưu tiên hỏi hợp tác, kết hôn, ký kết; gặp Khai/Sinh càng thuận."
    },
    {
      "system": "奇门",
      "element": "白虎",
      "reading": "Bạch Hổ — sát khí, máu me, kiện tụng, cứng rắn. Hung thương tật, va chạm; chỉ dùng khi cần áp chế, cưỡng chế, quân sự."
    },
    {
      "system": "奇门",
      "element": "玄武",
      "reading": "Huyền Vũ — trộm cắp, lừa đảo, tiểu nhân, thủy đạo. Cảnh báo mất mát/gian lận; tránh đầu tư mù quáng, kiểm soát dòng tiền."
    },
    {
      "system": "奇门",
      "element": "九地",
      "reading": "Cửu Địa — ẩn náu, phòng thủ, chậm chắc, đất đai. Tốt phòng thủ, mai phục, bất động sản; xấu tốc chiến, marketing ồn ào."
    },
    {
      "system": "奇门",
      "element": "九天",
      "reading": "Cửu Thiên — cao vút, xuất hành, thanh danh, tấn công. Tốt bay nhảy, thăng tiến, phát ngôn; gặp Khai Môn rất đẹp công danh."
    },
    {
      "system": "奇门",
      "element": "三奇得使",
      "reading": "Tam Kỳ đắc sứ — Ất/Bính/Đinh ở đúng cung được dùng (sứ mã), phát huy lực cứu. Báo hiệu thời cơ quý nhân thực sự; dùng khi chốt việc lớn trong giờ đó."
    },
    {
      "system": "奇门",
      "element": "三奇贵人",
      "reading": "Tam Kỳ quý nhân — Ất Bính Đinh hội tụ hoặc kỳ + Trực Phù/Lục Hợp. Rất tốt cầu cứu, thăng quan, hóa hung; ưu tiên hành động khi kỳ lâm cung dụng sự."
    },
    {
      "system": "奇门",
      "element": "乙奇",
      "reading": "Ất kỳ — ngày (nhu hòa), che chở, nữ quý, văn thư. Tốt hòa giải, cầu hôn, xin giúp đỡ mềm; kém hiệu trong xung đột cứng."
    },
    {
      "system": "奇门",
      "element": "丙奇",
      "reading": "Bính kỳ — mặt trời, uy quyền, chiếu sáng, phá tối. Tốt công khai chính nghĩa, thi cử, quan trường; mạnh khi gặp Khai/Cảnh."
    },
    {
      "system": "奇门",
      "element": "丁奇",
      "reading": "Đinh kỳ — sao, văn kiện, kỹ thuật, điểm phá. Tốt hợp đồng, bằng cấp, thủ đoạn tinh; gặp Tâm/Phụ hợp chuyên môn cao."
    },
    {
      "system": "奇门",
      "element": "天遁",
      "reading": "Thiên Độn — Bính kỳ + Trực Phù + Khai Môn (hoặc Cửu Thiên). Đại cát ẩn mình mà thành, xuất sư thuận; dùng xuất hành quan trọng, nhậm chức."
    },
    {
      "system": "奇门",
      "element": "地遁",
      "reading": "Địa Độn — Ất kỳ + Cửu Địa + Sinh Môn. Cát ẩn náu sinh tài, phòng thủ có lời; dùng đầu tư đất, ẩn cư phát triển."
    },
    {
      "system": "奇门",
      "element": "人遁",
      "reading": "Nhân Độn — Đinh kỳ + Thái Âm + Hưu Môn. Cát nhờ người/âm trợ, yên ổn; dùng cầu hòa, chữa bệnh, việc cần kín đáo."
    },
    {
      "system": "奇门",
      "element": "神遁",
      "reading": "Thần Độn — Bính kỳ + Cửu Thiên + Sinh Môn. Cát thần tốc danh lợi, thanh thế; dùng ra mắt sản phẩm, cầu danh lớn."
    },
    {
      "system": "奇门",
      "element": "鬼遁",
      "reading": "Quỷ Độn — Đinh kỳ + Cửu Địa + Đỗ Môn. Cát việc âm, huyền thuật, điều tra ngầm; không dùng chính danh công lộ."
    },
    {
      "system": "奇门",
      "element": "风遁",
      "reading": "Phong Độn — Ất kỳ + Lục Hợp + Sinh Môn. Cát giao thiệp, môi giới, hợp tác sinh tài; dùng ký kết, mai mối, sales."
    },
    {
      "system": "奇门",
      "element": "云遁",
      "reading": "Vân Độn — Ất kỳ + Thái Âm + Khai Môn. Cát che chở mà vẫn tiến, quan ẩn trợ; dùng xin việc, vận động ngầm."
    },
    {
      "system": "奇门",
      "element": "龙遁",
      "reading": "Long Độn — Ất kỳ + Cửu Địa + Khai Môn (thủy cục). Cát thủy lợi, đi xa bằng thủy, tài từ phương thấp; dùng xuất hành thủy đạo."
    },
    {
      "system": "奇门",
      "element": "虎遁",
      "reading": "Hổ Độn — Bính kỳ + Cửu Địa + Khai Môn. Cát uy mà vững, trấn áp; dùng nhậm chức nơi khó, thiết quân luật."
    },
    {
      "system": "奇门",
      "element": "青龙返首",
      "reading": "Thanh Long phản thủ — Lục Nghi (mậu) gia Khai Môn ở cung sinh vượng. Đại cát cầu tài công danh quay đầu thuận; chốt deal lớn trong giờ này."
    },
    {
      "system": "奇门",
      "element": "飞鸟跌穴",
      "reading": "Phi Điểu điệt huyệt — giá sử (thời can) lâm cung Trực Phù. Cát đắc vị, việc về đúng chỗ; dùng nhậm chức, về quê phát, chốt vị trí."
    },
    {
      "system": "奇门",
      "element": "白虎猖狂",
      "reading": "Bạch Hổ xương cuồng — Canh gia Bạch Hổ hoặc Canh+Thương/Tử. Đại hung thương tật, đâm chém, phá sản bạo; tuyệt xuất hành mạo hiểm, phẫu thuật không cấp."
    },
    {
      "system": "奇门",
      "element": "腾蛇妖娇",
      "reading": "Đằng Xà yêu kiều — Kỷ gia Đằng Xà, nghi hoặc mị hoặc. Hung lừa tình, hợp đồng ảo, tâm thần bất an; hoãn ký kết, soi xét đối tác."
    },
    {
      "system": "奇门",
      "element": "朱雀投江",
      "reading": "Chu Tước đầu giang — Đinh bị khắc/hãm thủy nặng, văn thư thất. Hung giấy tờ mất, thi trượt, hỏa tai liên quan nước; tránh nộp hồ sơ gấp."
    },
    {
      "system": "奇门",
      "element": "大格/刑格",
      "reading": "Đại Cách/Hình Cách — can xung hình với Nhật thời hoặc môn tinh xung khắc nặng. Báo trở ngại cứng, dễ hình sự khẩu thiệt; đổi giờ hoặc hoãn việc."
    },
    {
      "system": "六壬",
      "element": "贵人",
      "reading": "Quý Nhân — tối tôn, quý trợ, quan phủ. Được che chở, gặp cấp trên; dùng hỏi công danh, xin việc, kiện tụng cần thế lực."
    },
    {
      "system": "六壬",
      "element": "螣蛇",
      "reading": "Đằng Xà — kinh sợ, giả dối, biến ảo, mộng mị. Cảnh báo lừa gạt, tin đồn; xấu hôn nhân/ký kết, tốt điều tra gian tình."
    },
    {
      "system": "六壬",
      "element": "朱雀",
      "reading": "Chu Tước — văn thư, khẩu thiệt, tin tức, huyết quang nhẹ. Tốt thi cử/giấy tờ; hung tranh cãi, kiện cáo lời nói."
    },
    {
      "system": "六壬",
      "element": "六合",
      "reading": "Lục Hợp — hòa hợp, hôn nhân, môi giới, bí mật. Cực tốt kết hôn, hợp tác, mai mối; che giấu việc riêng."
    },
    {
      "system": "六壬",
      "element": "勾陈",
      "reading": "Câu Trần — trì trệ, đất đai, kiện tụng dai dẳng, trói buộc. Hung dây dưa; dùng hỏi bất động sản, tranh chấp lâu năm."
    },
    {
      "system": "六壬",
      "element": "青龙",
      "reading": "Thanh Long — tài lộc, vui vẻ, rượu thịt, quý khí. Tốt cầu tài, ăn uống, hỷ sự; tránh phóng đãng nếu quá vượng."
    },
    {
      "system": "六壬",
      "element": "天空",
      "reading": "Thiên Không — hư không, lừa dối, tăng đạo, lời hứa suông. Cảnh báo không có thực; tránh đầu tư, đòi nợ khó thu."
    },
    {
      "system": "六壬",
      "element": "白虎",
      "reading": "Bạch Hổ — tang thương, binh đao, bệnh nặng, đường sá. Hung tai nạn/phẫu thuật; mạnh khi cần uy, cưỡng chế."
    },
    {
      "system": "六壬",
      "element": "太常",
      "reading": "Thái Thường — y phục, rượu lễ, ổn định, nông sản. Tốt hôn lễ, bổng lộc thường; hơi chậm, hợp việc chính thống."
    },
    {
      "system": "六壬",
      "element": "玄武",
      "reading": "Huyền Vũ — trộm cắp, gian dâm, lừa đảo, tiểu nhân. Cảnh báo mất của/ngoại tình; kiểm soát bảo mật và trung thành."
    },
    {
      "system": "六壬",
      "element": "太阴",
      "reading": "Thái Âm — che đậy, nữ quý, kế hoạch kín, tài liệu. Tốt mưu sự ban đêm, nhờ nữ trợ; xấu phơi bày công khai."
    },
    {
      "system": "六壬",
      "element": "天后",
      "reading": "Thiên Hậu — phụ nữ, che chở, dâm thích, âm thấp. Tốt nhờ nữ quý/mẹ vợ; thận trọng sắc dục, việc thủy đạo."
    },
    {
      "system": "六壬",
      "element": "四课",
      "reading": "Tứ khóa — nhật dương, nhật âm, thần dương, thần âm. Nền tảng xem quan hệ chủ-khách-sự; dùng xác định ai chủ động, xung đột ở đâu."
    },
    {
      "system": "六壬",
      "element": "三传",
      "reading": "Tam truyền — sơ, trung, mạt truyền. Diễn biến đầu-giữa-cuối việc; đọc tuần tự để biết khởi, biến, kết."
    },
    {
      "system": "六壬",
      "element": "元首课",
      "reading": "Nguyên Thủ — thượng khắc hạ, một khóa làm đầu. Việc do cấp trên/chủ động áp xuống, nhanh gọn; dùng khi hỏi quan hệ trên dưới, quyết định từ trên."
    },
    {
      "system": "六壬",
      "element": "重审课",
      "reading": "Trọng Thẩm — hạ tặc thượng, âm mưu dưới lật. Việc từ dưới phản, cần xem xét lại; dùng kiện tụng, nội bộ phản kháng."
    },
    {
      "system": "六壬",
      "element": "知一课",
      "reading": "Tri Nhất — hai thượng khắc hạ, lấy涉害/ưu tiên. Tình thế phân vân hai hướng; chọn phía ít hại hơn, tránh ôm đồm."
    },
    {
      "system": "六壬",
      "element": "涉害课",
      "reading": "Thiệp Hại — nhiều khắc, lấy sâu hại nhất. Việc gian nan, phải chịu tổn hao mới xong; dùng khi biết trước sẽ vất vả."
    },
    {
